FUNCTION_BLOCK FB_SBSP_MicrowaveSteering
VAR_INPUT
    (* Orbital Master Command and Safety *)
    bSystemEnable           : BOOL;     (* Master enable from orbital control station *)
    bEmergencyShutoff       : BOOL;     (* Fast-acting safety relay OK signal, FALSE = Trip *)

    (* Critical Telemetry & Rectenna Tracking *)
    rRetrodirectivePhase    : REAL;     (* Pilot signal phase feedback from ground rectenna (rad) *)
    rPilotSignalStrength    : REAL;     (* Received RSSI from pilot tone (dBm) *)

    (* System Health & Environment *)
    rKlystronTemp           : REAL;     (* Critical thermal feedback from klystron cavities (Kelvin) *)
    rPlasmaWakeDensity      : REAL;     (* LEO plasma wake density mapping (electrons/m^3) *)
    rBeamDeviationX         : REAL;     (* X-axis deviation error from target centroid (m) *)
    rBeamDeviationY         : REAL;     (* Y-axis deviation error from target centroid (m) *)
END_VAR

VAR_OUTPUT
    (* Beam Actuation & Steering *)
    bTransmissionReady      : BOOL;     (* High-power transmission interlocks clear *)
    rPhaseCorrection        : REAL;     (* Calculated phase array correction for steering (rad) *)
    rThermalControlValve    : REAL;     (* Klystron multi-cavity cooling jacket valve command (0.0-100.0%) *)
    rOutputPowerSetpoint    : REAL;     (* Requested microwave output power (MW) *)

    (* Alarms & Faults *)
    bPlasmaWarning          : BOOL;     (* High plasma wake interference detected *)
    bKlystronTrip           : BOOL;     (* Thermal trip threshold exceeded *)
    bBeamDefocusAlarm       : BOOL;     (* Rectenna loss of lock or extreme deviation *)
END_VAR

VAR
    (* Internal State & Timers *)
    iOperatingState         : INT := 0; (* 0: INIT, 10: THERM_PREP, 20: PHASE_LOCK, 30: TX_ACTIVE, 99: FAULT *)
    tWarmupTimer            : TON;
    tPlasmaTransientTimer   : TON;

    (* PID & Mathematical State Variables *)
    rIntegralErrorX         : REAL := 0.0;
    rIntegralErrorY         : REAL := 0.0;
    rDerivativeX            : REAL := 0.0;
    rLastDeviationX         : REAL := 0.0;

    (* Constants & Tuning Parameters *)
    rMaxTempLimit           : REAL := 395.5;    (* Maximum safe operational temp in K *)
    rPlasmaDensityThreshold : REAL := 1.5E11;   (* Max acceptable wake density *)
    rGainP                  : REAL := 1.452;    (* Proportional steering gain *)
    rGainI                  : REAL := 0.015;    (* Integral steering gain *)
    rGainD                  : REAL := 0.125;    (* Derivative steering gain *)
    rDt                     : REAL := 0.01;     (* 10ms execution cycle time *)

    (* Intermediate Calculations *)
    rPlasmaPhaseShift       : REAL := 0.0;
    rVectorMagnitude        : REAL := 0.0;
    rThermalDelta           : REAL := 0.0;
END_VAR

(* === MAIN LOGIC === *)

(* 1. Immediate Safety Interlocks (Highest Priority) *)
IF NOT bEmergencyShutoff OR (rKlystronTemp > rMaxTempLimit) THEN
    iOperatingState := 99;
    bTransmissionReady := FALSE;
    rOutputPowerSetpoint := 0.0;

    IF (rKlystronTemp > rMaxTempLimit) THEN
        bKlystronTrip := TRUE;
        rThermalControlValve := 100.0; (* Full cooling override *)
    END_IF;

    RETURN;
END_IF;

(* 2. Klystron Thermal Cascading & Dynamic Cooling *)
(* Active thermal management runs independent of TX state to ensure survival *)
rThermalDelta := rMaxTempLimit - rKlystronTemp;
IF rThermalDelta < 15.0 THEN
    rThermalControlValve := 100.0 - (rThermalDelta * 6.66); (* Proportional ramp near limit *)
ELSIF rThermalDelta < 50.0 THEN
    rThermalControlValve := 25.0; (* Steady state holding flow *)
ELSE
    rThermalControlValve := 5.0; (* Minimum bypass *)
END_IF;

(* 3. LEO Plasma Wake Disturbance Mapping *)
(* Compensate for dispersion phase shift caused by localized electron density transients *)
IF rPlasmaWakeDensity > rPlasmaDensityThreshold THEN
    bPlasmaWarning := TRUE;
    tPlasmaTransientTimer(IN := TRUE, PT := T#2S);

    (* Estimate phase delay via Appleton-Hartree approximation simplifications *)
    rPlasmaPhaseShift := (rPlasmaWakeDensity / 1.0E12) * 0.045; 
ELSE
    bPlasmaWarning := FALSE;
    tPlasmaTransientTimer(IN := FALSE, PT := T#2S);
    rPlasmaPhaseShift := 0.0;
END_IF;

(* Fallback trip if plasma interference is sustained *)
IF tPlasmaTransientTimer.Q THEN
    iOperatingState := 99; 
END_IF;

(* 4. Main SBSP Operational State Machine *)
CASE iOperatingState OF
    0: (* INIT - System Safed *)
        bTransmissionReady := FALSE;
        rOutputPowerSetpoint := 0.0;
        bBeamDefocusAlarm := FALSE;

        IF bSystemEnable AND bEmergencyShutoff THEN
            iOperatingState := 10;
        END_IF;

    10: (* THERM_PREP - Warmup Klystron Cathodes *)
        tWarmupTimer(IN := TRUE, PT := T#45S);

        IF tWarmupTimer.Q THEN
            tWarmupTimer(IN := FALSE);
            iOperatingState := 20;
        END_IF;

    20: (* PHASE_LOCK - Acquire Retrodirective Pilot Signal *)
        IF rPilotSignalStrength > -85.0 THEN (* Sufficient RSSI to lock *)
            rOutputPowerSetpoint := 1.0; (* Pilot tracking power (MW) *)
            iOperatingState := 30;
        ELSE
            bBeamDefocusAlarm := TRUE;
        END_IF;

    30: (* ACTIVE_TRANSMISSION - Phased-Array Beam Steering & Power Transfer *)
        bTransmissionReady := TRUE;
        rOutputPowerSetpoint := 250.0; (* Nominal transmission power (MW) *)

        (* Closed-loop PID centroid deviation tracking *)
        rIntegralErrorX := rIntegralErrorX + (rBeamDeviationX * rDt);
        rDerivativeX := (rBeamDeviationX - rLastDeviationX) / rDt;
        rLastDeviationX := rBeamDeviationX;

        rVectorMagnitude := SQRT((rBeamDeviationX * rBeamDeviationX) + (rBeamDeviationY * rBeamDeviationY));

        IF rVectorMagnitude > 500.0 THEN (* 500m beam wandering = defocus fault *)
            bBeamDefocusAlarm := TRUE;
            iOperatingState := 99;
        ELSE
            bBeamDefocusAlarm := FALSE;
            (* Apply PID and Retrodirective Pilot Phase, with Plasma dispersion subtraction *)
            rPhaseCorrection := rRetrodirectivePhase 
                              + (rGainP * rBeamDeviationX) 
                              + (rGainI * rIntegralErrorX) 
                              + (rGainD * rDerivativeX)
                              - rPlasmaPhaseShift;
        END_IF;

        IF NOT bSystemEnable THEN
            iOperatingState := 0;
        END_IF;

    99: (* FAULT / TRIP *)
        bTransmissionReady := FALSE;
        rOutputPowerSetpoint := 0.0;

        (* Latch until master enable cycled and faults cleared *)
        IF NOT bSystemEnable AND NOT bKlystronTrip AND NOT bPlasmaWarning THEN
            iOperatingState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
